create extension if not exists pgcrypto;
create table warehouses(id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, city text not null, latitude double precision not null, longitude double precision not null, status text not null, checkin_code text not null unique, load_percent int not null default 0 check(load_percent between 0 and 100));
create table products(id uuid primary key default gen_random_uuid(), sku text not null unique, barcode text not null unique, name text not null, category text not null, price_paise int not null check(price_paise>=0), reorder_point int not null default 10 check(reorder_point>=0));
create table bins(id uuid primary key default gen_random_uuid(), warehouse_id uuid not null references warehouses, row_code text not null, code text not null, location_code text not null unique, x double precision not null, y double precision not null, width double precision not null check(width>0), height double precision not null check(height>0), capacity int not null check(capacity>0), access_node text not null);
create table inventory_locations(id uuid primary key default gen_random_uuid(), product_id uuid not null references products, warehouse_id uuid not null references warehouses, bin_id uuid not null references bins, quantity_on_hand int not null check(quantity_on_hand>=0), quantity_reserved int not null default 0 check(quantity_reserved>=0 and quantity_reserved<=quantity_on_hand), unique(product_id,bin_id));
create table orders(id uuid primary key default gen_random_uuid(), code text not null unique, customer_name text not null, status text not null check(status in ('PLACED','ALLOCATING','ALLOCATED','WAITING_FOR_PICK','PICKING','PICKED','AT_CHECKIN','READY_FOR_DISPATCH','DISPATCHED','COMPLETED','CANCELLED','EXCEPTION')), warehouse_id uuid references warehouses, total_paise int not null check(total_paise>=0), allocation_reason text, is_simulated boolean not null default false, created_at timestamptz not null default now());
create table order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references orders, product_id uuid not null references products, quantity int not null check(quantity>0));
create table inventory_reservations(id uuid primary key default gen_random_uuid(), order_id uuid not null references orders, inventory_location_id uuid not null references inventory_locations, quantity int not null check(quantity>0), status text not null, created_at timestamptz not null default now());
create table pick_tasks(id uuid primary key default gen_random_uuid(), code text not null unique, order_id uuid not null references orders, warehouse_id uuid not null references warehouses, employee_code text, status text not null check(status in ('ASSIGNED','STARTED','IN_PROGRESS','EXCEPTION','COMPLETED','CANCELLED')), route_json jsonb not null, total_distance double precision not null check(total_distance>=0), created_at timestamptz not null default now());
create table pick_task_items(id uuid primary key default gen_random_uuid(), pick_task_id uuid not null references pick_tasks, order_item_id uuid not null references order_items, inventory_location_id uuid not null references inventory_locations, sequence int not null check(sequence>0), quantity int not null check(quantity>0), status text not null);
create table stock_movements(id uuid primary key default gen_random_uuid(), product_id uuid not null references products, warehouse_id uuid not null references warehouses, source_bin_id uuid references bins, destination_bin_id uuid references bins, quantity int not null check(quantity>0), movement_type text not null check(movement_type in ('INWARD','OUTWARD','TRANSFER','ADJUSTMENT','RESERVATION_RELEASE','DAMAGED','MISSING')), order_id uuid references orders, employee_code text, reference_id text not null, created_at timestamptz not null default now(), metadata jsonb not null default '{}');
create table inventory_exceptions(id uuid primary key default gen_random_uuid(), pick_task_item_id uuid not null references pick_task_items, product_id uuid not null references products, warehouse_id uuid not null references warehouses, bin_id uuid not null references bins, employee_code text not null, resolution text, created_at timestamptz not null default now());
create index idx_products_name on products using gin(to_tsvector('simple',name)); create index idx_inventory_product on inventory_locations(product_id); create index idx_inventory_bin on inventory_locations(bin_id); create index idx_orders_status_warehouse on orders(status,warehouse_id); create index idx_movements_product_created on stock_movements(product_id,created_at desc);
